function HasCloseElements(numbers : array of real; threshold : real): boolean; 
var
  i, j : integer;
begin
  for i := 0 to length(numbers) - 1 do
    for j := i + 1 to length(numbers) do
      if abs(numbers[i] - numbers[j]) < threshold then
        exit(true);
  Result := false;
end;


function SeparateParenGroups(parenString : string): array of string;
var
  openParens, closeParens, start, i: integer;
  result: array of string;
begin
  setlength(result, 0);
  openParens := 0;
  start := 1;
  for i := 1 to length(parenString) do
  begin
    if parenString[i] = '(' then
      inc(openParens)
    else if parenString[i] = ')' then
      dec(openParens);

    if openParens = 0 then
    begin
      setlength(result, length(result) + 1);
      result[length(result) - 1] := copy(parenString, start, i - start);
      start := i + 1;
    end;
  end;
  if openParens <> 0 then
    raise Exception.Create('Unbalanced parentheses');
  Result := result;
end;


function TruncateNumber(number : real): real;
begin
  Result := Trunc(number - Trunc(number));
end;


function BelowZero(operations : array of integer): boolean;
var
    balance : integer := 0;
begin
    for var operation in operations do
    begin
        balance := balance + operation;
        if balance < 0 then
            exit(True);
    end;
    exit(False);
end;


function MeanAbsoluteDeviation(numbers : array of real): real; 
var
    mean, sum, mad : real;
    i : integer;
begin
    mean := 0;
    for i := 0 to Length(numbers) - 1 do
        mean := mean + numbers[i];
    mean := mean / Length(numbers);

    sum := 0;
    for i := 0 to Length(numbers) - 1 do
        sum := sum + Abs(numbers[i] - mean);

    mad := sum / Length(numbers);
    Result := mad;
end;


function Intersperse(numbers : array of integer; delimeter : integer): array of integer;
var
    i : integer;
begin
    if Length(numbers) = 0 then
        Exit(numbers);

    SetLength(Result, Length(numbers) * 2 - 1);
    for i := 0 to High(numbers) do
    begin
        Result[i] := numbers[i];
        if i < High(numbers) then
            Result[i + 1] := delimeter;
    end;
end;


function ParseNestedParens(parenString : string): array of integer;
var
  i, j, k, l, maxLevel, currentLevel, maxLevels: integer;
  result: array of integer;
begin
  result := [];
  maxLevels := 0;
  for i := 1 to length(parenString) do
  begin
    if parenString[i] = ' ' then
    begin
      if currentLevel > maxLevel then
        maxLevel := currentLevel;
      currentLevel := 0;
    end
    else
    begin
      currentLevel := currentLevel + 1;
    end;
  end;
  if currentLevel > maxLevel then
    maxLevel := currentLevel;
  SetLength(result, maxLevel + 1);
  result[maxLevel] := maxLevel;
  Dec(maxLevel);
  while maxLevel >= 0 do
  begin
    l := 0;
    for j := i downto 1 do
    begin
      if parenString[j] = '(' then
        Inc(l)
      else
        Dec(l);
      if l = 0 then
      begin
        result[maxLevel] := maxLevel;
        Dec(maxLevel);
        i := j;
        break;
      end;
    end;
  end;
  ParseNestedParens := result;
end;


function FilterBySubstring(strings : array of string; substring : string): array of string;
var
  i, j: integer;
  result: array of string;
begin
  SetLength(result, Length(strings));
  i := 0;
  for j := 0 to High(strings) do
    if Pos(substring, strings[j]) > 0 then
    begin
      result[i] := strings[j];
      Inc(i);
    end;
  Result := result;
end;


function SumProduct(numbers : array of integer): array of integer; 
begin
  if length(numbers) = 0 then
    result := [0, 1]
  else
    begin
      var sum := 0;
      var product := 1;
      for var i := 1 to length(numbers) do
        begin
          sum := sum + numbers[i];
          product := product * numbers[i];
        end;
      result := [sum, product];
    end;
end;


function RollingMax(numbers : array of integer): array of integer; 
