end;

function ReverseString(const s: string): string;
{ Reverse the given string }
var
  i, len: integer;
begin
  len := Length(s);
  SetLength(Result, len);
  for i := 1 to len do
    Result[i] := s[len - i + 1];
end;
function IsPalindrome(s: string): boolean;
{ Test if given string is a palindrome }
begin
  Result := s = ReverseString(s);
end;
function MakePalindrome(str: string): string;
{ Find the shortest palindrome that begins with a supplied string.
  Algorithm idea is simple:
  - Find the longest postfix of supplied string that is a palindrome.
  - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
  >>> MakePalindrome('')
  ''
  >>> MakePalindrome('cat')
  'catac'
  >>> MakePalindrome('cata')
  'catac' }
var
  i, j, len, maxLen: integer;
  prefix, suffix: string;
begin
  len := Length(str);
  maxLen := 0;
  Result := '';
  for i := 1 to len do
  begin
    prefix := Copy(str, 1, i);
    if IsPalindrome(prefix) then
    begin
      j := len - i + 1;
      suffix := ReverseString(Copy(str, j, len - j + 1));
      if Length(suffix) > maxLen then
      begin
        maxLen := Length(suffix);
        Result := str + ReverseString(Copy(str, 1, i));
      end;
    end;
  end;
end;


function StringXor(a, b: string): string;
var
  i: integer;
begin
  if Length(a) <> Length(b) then
    raise Exception.Create('Strings must be of equal length');

  Result := '';
  for i := 1 to Length(a) do
  begin
    if a[i] = b[i] then
      Result := Result + '0'
    else
      Result := Result + '1';
  end;
end;


