function CountDistinctCharacters(str : string): integer;
var
    distinctCharacters : set of char;
    count : integer;
begin
    distinctCharacters := TSet<char>.Create;
    count := 0;

    for var c := str to str do
    begin
        if not distinctCharacters.Contains(c) then
        begin
            distinctCharacters.Add(c);
            count := count + 1;
        end;
    end;

    Result := count;
end;


function ParseMusic(musicString : string): array of integer;
var
    note: char;
    beat: integer;
    result: array of integer;
    i, j: integer;
begin
    SetLength(result, Length(musicString));
    i := 0;
    j := 0;
    while i < Length(musicString) do
    begin
        note := musicString[i];
        beat := 0;
        if note = 'o' then
            beat := 4
        else if note = 'o' then
            beat := 2
        else if note = '.' then
            beat := 1;
        result[j] := beat;
        Inc(i);
        Inc(j);
    end;
    ParseMusic := result;
end;


function HowManyTimes(str : string; substring : string): integer; 
var
    i, j, count: integer;
begin
    count := 0;
    for i := 1 to length(str) - length(substring) + 1 do
    begin
        j := 1;
        while (j <= length(substring)) and (str[i+j-1] = substring[j]) do
        begin
            j := j + 1;
        end;
        if j > length(substring) then
        begin
            count := count + 1;
            j := 0;
        end;
    end;
    HowManyTimes := count;
end;


function SortNumbers(numbers : string): string;
var
    numberList: array of string;
    i, j, minIndex: integer;
    temp: string;
begin
    numberList := strings.Split(numbers, ' ');
    for i := 0 to high(numberList) do
    begin
        minIndex := i;
        for j := i + 1 to high(numberList) do
        begin
            if (numberList[j] < numberList[minIndex]) then
                minIndex := j;
        end;
        temp := numberList[i];
        numberList[i] := numberList[minIndex];
        numberList[minIndex] := temp;
    end;
    result := strings.Join(numberList, ' ');
end;


function FindClosestElements(numbers : array of real): array of real;
var
    minDifference, i, j, minIndex1, minIndex2: integer;
begin
    minDifference := MaxInt64;
    for i := 1 to High(numbers) do
        for j := i + 1 to High(numbers) do
        begin
            if Abs(numbers[i] - numbers[j]) < minDifference then
            begin
                minDifference := Abs(numbers[i] - numbers[j]);
                minIndex1 := i;
                minIndex2 := j;
            end;
        end;
    Result[1] := numbers[minIndex1];
    Result[2] := numbers[minIndex2];
end;


function RescaleToUnit(numbers : array of real): array of real;
var
    min, max, i: real;
begin
    min := numbers[0];
    max := numbers[0];

    // Find the minimum and maximum values in the array
    for i := 1 to length(numbers) do
    begin
        if numbers[i] < min then
            min := numbers[i];
        if numbers[i] > max then
            max := numbers[i];
    end;

    // Rescale the array
    for i := 0 to length(numbers) - 1 do
        numbers[i] := (numbers[i] - min) / (max - min);

    Result := numbers;
end;


function FilterIntegers(values : array of Variant): array of integer; 
var
  i, j, count: integer;
  temp: Variant;
begin
  count := 0;
  SetLength(result, Length(values));

  for i := 0 to High(values) do
  begin
    if VarIsNull(values[i]) then
      Continue;

    if VarIsType(values[i], varInteger) then
    begin
      result[count] := values[i];
      Inc(count);
    end;
  end;

  SetLength(result, count);
end;


