function Factorize(n : integer): array of integer; 
var
    i, j, count : integer;
begin
    result := [];
    for i := 2 to n do
    begin
        count := 0;
        while (n mod i = 0) do
        begin
            n := n div i;
            count := count + 1;
        end;
        if count > 0 then
            result := result + [i, count];
    end;
end;


function RemoveDuplicates(numbers : array of integer): array of integer;
var
  i, j, count: integer;
  uniqueNumbers: array of integer;
begin
  SetLength(uniqueNumbers, 0);
  for i := 0 to High(numbers) do
  begin
    count := 0;
    for j := 0 to High(uniqueNumbers) do
    begin
      if numbers[i] = uniqueNumbers[j] then
        count := count + 1;
    end;
    if count = 0 then
      SetLength(uniqueNumbers, Length(uniqueNumbers) + 1);
    uniqueNumbers[j] := numbers[i];
  end;
  Result := uniqueNumbers;
end;


