function IsPrime(n : integer): boolean;  {Return true if a given number is prime, and false otherwise.
begin
  if (n <= 1) then
    result := False
  else
    result := True;
    for i := 2 to sqrt(n) do
    begin
      if (n mod i = 0) then
        exit(False);
    end;
  end;
end;

function Power(x: real; n: integer): real;
{ Calculate x raised to the power of n }
var
  i: integer;
  result_power: real;
begin
  result_power := 1.0;
  for i := 1 to n do
    result_power := result_power * x;
  Power := result_power;
end;
function Poly(xs: array of real; x: real): real;
{ Evaluates polynomial with coefficients xs at point x.
  return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n }
var
  i: integer;
  result: real;
begin
  result := 0.0;
  for i := 0 to Length(xs) - 1 do
    result := result + xs[i] * Power(x, i);
  Poly := result;
end;
function FindZero(xs: array of real): real;
{ xs are coefficients of a polynomial.
  FindZero find x such that poly(x) = 0.
  FindZero returns only only zero point, even if there are many.
  Moreover, FindZero only takes list xs having even number of coefficients
  and largest non zero coefficient as it guarantees
  a solution.
  >>> round(FindZero([1, 2]), 2) # f(x) = 1 + 2x
  -0.5
  >>> round(FindZero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
  1.0 }
var
  i: integer;
  x: real;
  poly_value: real;
begin
  for x := -100.0 to 100.0 do
  begin
    poly_value := Poly(xs, x);
    if Round(poly_value, 2) = 0.0 then
      Exit(x);
  end;
  FindZero := -1.0;
end;


function SortThird(l : array of integer): array of integer;
var
    i, j, k, temp: integer;
begin
    for i := 0 to length(l) - 1 do
    begin
        if (i + 1) mod 3 = 0 then
        begin
            temp := l[i];
            j := i;
            while (j > 0) and (l[j - 1] > temp) do
            begin
                l[j] := l[j - 1];
                j := j - 1;
            end;
            l[j] := temp;
        end;
    end;
    Result := l;
end;


function Unique(l : array of integer): array of integer; 
var
    i, j, n: integer;
    temp: integer;
begin
    SetLength(result, Length(l));
    for i := 0 to High(l) do
    begin
        temp := l[i];
        for j := i + 1 to High(l) do
        begin
            if temp = l[j] then
            begin
                n := j;
                while n < High(l) do
                begin
                    Inc(n);
                    if l[n] <> l[j] then
                    begin
                        l[n] := l[j];
                    end;
                end;
                SetLength(result, Length(result) - 1);
                Break;
            end;
        end;
    end;
    SetLength(result, Length(result));
    for i := 0 to High(result) do
    begin
        for j := i + 1 to High(result) do
        begin
            if result[i] > result[j] then
            begin
                temp := result[i];
                result[i] := result[j];
                result[j] := temp;
            end;
        end;
    end;
end;


