function SortEven(l : array of integer): array of integer;
var
    evenIndices: array of integer;
    i, j, temp: integer;
begin
    SetLength(evenIndices, 0);
    for i := 0 to High(l) do
    begin
        if (i mod 2 = 0) then
            SetLength(evenIndices, Length(evenIndices) + 1)
        else
            SetElement(evenIndices, Length(evenIndices) - 1, l[i]);
    end;

    for i := 0 to High(evenIndices) do
    begin
        for j := i + 1 to High(evenIndices) do
        begin
            if evenIndices[i] > evenIndices[j] then
            begin
                temp := evenIndices[i];
                evenIndices[i] := evenIndices[j];
                evenIndices[j] := temp;
            end;
        end;
    end;

    SetLength(l, 0);
    for i := 0 to High(evenIndices) do
    begin
        SetLength(l, Length(l) + 1);
        l[i] := evenIndices[i];
    end;

    Result := l;
end;

function EncodeCyclic(s: string): string;
{ returns encoded string by cycling groups of three characters. }
var
  groups: array of string;
  i, j, group_length, group_count: integer;
  temp: string;
begin
  i := 1;
  group_count := 0;
  SetLength(groups, (Length(s) + 2) div 3);
  while i <= Length(s) do
  begin
    group_length := 3;
    if (i + 2) > Length(s) then
      group_length := Length(s) - i + 1;
    groups[group_count] := Copy(s, i, group_length);
    i := i + 3;
    group_count := group_count + 1;
  end;
  for j := 0 to group_count - 1 do
  begin
    if Length(groups[j]) = 3 then
    begin
      temp := groups[j];
      groups[j] := temp[2] + temp[3] + temp[1];
    end;
  end;
  Result := '';
  for j := 0 to group_count - 1 do
    Result := Result + groups[j];
end;
function DecodeCyclic(s: string): string;
{ takes as input string encoded with encode_cyclic function. Returns decoded string. }
var
  groups: array of string;
  i, j, group_length, group_count: integer;
  temp: string;
begin
  i := 1;
  group_count := 0;
  SetLength(groups, (Length(s) + 2) div 3);

  while i <= Length(s) do
  begin
    group_length := 3;
    if (i + 2) > Length(s) then
      group_length := Length(s) - i + 1;

    groups[group_count] := Copy(s, i, group_length);
    i := i + 3;
    group_count := group_count + 1;
  end;

  for j := 0 to group_count - 1 do
  begin
    if Length(groups[j]) = 3 then
    begin
      temp := groups[j];
      groups[j] := temp[3] + temp[1] + temp[2];
    end;
  end;

  Result := '';
  for j := 0 to group_count - 1 do
    Result := Result + groups[j];
end;


function PrimeFib(n : integer): integer;
var
  i, count, fib1, fib2, fib3, primeCount, fibPrimeCount: integer;
  prime: boolean;
begin
  count := 0;
  fib1 := 0;
  fib2 := 1;
  fib3 := 0;
  primeCount := 0;
  fibPrimeCount := 0;
  while count < n do
  begin
    if IsPrime(fib3) then
    begin
      primeCount := primeCount + 1;
      if primeCount = n then
        exit(fib3);
    end;
    if primeCount = n then
      exit(fib3);
    fibPrimeCount := fibPrimeCount + 1;
    if fibPrimeCount = n then
      exit(fib3);
    if fibPrimeCount = primeCount then
    begin
      fibPrimeCount := 0;
      fib3 := fib1 + fib2;
      fib1 := fib2;
      fib2 := fib3;
      count := count + 1;
    end;
  end;
end;


function TriplesSumToZero(l : array of integer): boolean; 
