  i, j, k: integer;
begin
  for i := 0 to length(l) - 3 do
  begin
    for j := i + 1 to length(l) - 2 do
    begin
      for k := j + 1 to length(l) do
      begin
        if l[i] + l[j] + l[k] = 0 then
          exit(True);
      end;
    end;
  end;
  exit(False);
end;


