function ChangeBase(x : integer; base : integer): string; 
var
    remainder, quotient, i : integer;
    result : string;
begin
    result := '';
    quotient := x;
    while quotient > 0 do
    begin
        remainder := quotient mod base;
        quotient := quotient div base;
        if remainder < 10 then
            result := char(remainder + ord('0')) + result
        else
            result := chr(remainder - 10 + ord('A')) + result;
    end;
    if quotient > 0 then
        result := chr(quotient + ord('0')) + result;
    ChangeBase := result;
end;


function TriangleArea(a, h : real): real; 
