function Fib4(n : integer): integer;
var
    i, a, b, c, d, e : integer;
begin
    if n < 4 then
    begin
        case n of
            0: result := 0;
            1: result := 0;
            2: result := 2;
            3: result := 0;
        end;
    end
    else
    begin
        a := 0;
        b := 0;
        c := 2;
        d := 0;
        e := 0;
        for i := 4 to n do
        begin
            e := d + c + c + b;
            b := c;
            c := d;
            d := e;
        end;
        result := e;
    end;
end;


function Median(l : array of integer): real; 
var
    n: integer;
    i, j: integer;
    pivot, pivot_index: integer;
    temp: real;
begin
    n := length(l);
    if n mod 2 = 0 then
    begin
        pivot_index := n div 2;
        j := pivot_index - 1;
        i := pivot_index;
        while i < n do
        begin
            if l[i] < l[pivot_index] then
            begin
                dec(j);
                if j < 0 then
                begin
                    pivot := l[i];
                    while i < n do
                    begin
                        temp := l[i];
                        l[i] := l[j];
                        l[j] := temp;
                        dec(i);
                        dec(j);
                    end;
                end
                else
                begin
                    pivot := l[j];
                    while j >= 0 do
                    begin
                        temp := l[j];
                        l[j] := l[i];
                        l[i] := temp;
                        inc(i);
                        dec(j);
                    end;
                end;
            end;
            inc(i);
        end;
