    end
    else
        sign := 1;

    if (b < 0) then
    begin
        sign := -1;
        b := -b;
    end
    else
        sign := 1;

    product := 0;

    while (b > 0) do
    begin
        if (b mod 10) = 1 then
            product := product + a;

        a := a * 10;
        b := b div 10;
    end;

    result := sign * product;
end;


