begin
    evenCount := 0;
    oddCount := 0;
    for i := 1 to n do
    begin
        count := 0;
        temp := i;
        while temp > 0 do
        begin
            inc(count);
            temp := temp div 10;
        end;
        palindrome[i] := i;
        for j := 1 to count div 2 do
        begin
            if (palindrome[i] mod 10) <> (palindrome[i - j] mod 10) then
                exit;
            palindrome[i] := palindrome[i] div 10;
            if (palindrome[i] mod 10) <> (palindrome[i - j] mod 10) then
                exit;
            palindrome[i] := palindrome[i] div 10;
        end;
        if (palindrome[i] mod 2 = 0) then
            inc(evenCount)
        else
            inc(oddCount);
    end;
    EvenOddPalindrome[1] := evenCount;
    EvenOddPalindrome[2] := oddCount;
end;


