end;


function GetOddCollatz(n : integer): array of integer;
var
    sequence: array of integer;
    i, j, oddCount, nextOdd: integer;
begin
    SetLength(sequence, 1000);
    sequence[0] := n;
    oddCount := 1;
    j := 1;

    while n <> 1 do
    begin
        if n mod 2 <> 0 then
        begin
            nextOdd := 3 * n + 1;
            if nextOdd > 1000 then
                SetLength(sequence, Length(sequence) + 1000);
            sequence[j] := nextOdd;
            oddCount := oddCount + 1;
        end
        else
            n := n div 2;

        j := j + 1;
    end;

    SetLength(sequence, oddCount);
    for i := 0 to j - 1 do
        if sequence[i] mod 2 <> 0 then
            sequence[i] := sequence[i];

    Result := sequence;
end;


function ValidDate(date : string): boolean;
var
    month, day, year : integer;
    parts : array of string;
begin
    // Check if the date string is empty
    if date = '' then
        exit(False);

    // Split the date string into parts
    parts := split('-', date);

    // Check if there are exactly 3 parts
    if length(parts) <> 3 then
        exit(False);

    // Extract the day, month, and year from the parts
    day := strtoint(parts[0]);
    month := strtoint(parts[1]);
    year := strtoint(parts[2]);

    // Check if the day, month, and year are valid
    if (day < 1) or (day > 31) or (month < 1) or (month > 12) or (year < 1) then
        exit(False);

    // Check if the day is valid for the month
    if month = 2 then
    begin
        if day > 29 then
            exit(False);
    end
    else if month = 4 then
    begin
        if day > 30 then
            exit(False);
    end
    else if month = 6 then
    begin
        if day > 30 then
            exit(False);
    end
    else if month = 9 then
    begin
        if day > 30 then
            exit(False);
    end
    else if month = 1 then
    begin
        if day > 31 then
            exit(False);
    end;

    // If all checks pass, the date is valid
    exit(True);
end;


function SplitWords(txt: string): Variant;
begin
  if txt = '' then
    Result := 0
  else
    if Pos(',', txt) > 0 then
      Result := Split(txt, ',')
    else
      Result := CountLowerCaseWithOddOrder(txt);
end;

function CountLowerCaseWithOddOrder(const txt: string): Integer;
var
  i, count: Integer;
  ch: Char;
begin
  count := 0;
  for i := 0 to Length(txt) - 1 do
  begin
    ch := LowerCase(txt[i]);
    if (ch >= 'a') and (ch <= 'z') and (Ord(ch) - Ord('a') mod 2 = 1) then
      Inc(count);
  end;
  Result := count;
end;

function Split(const txt: string; const delimiter: string): TArray<string>;
var
  pos: Integer;
begin
  Result := TArray<string>.Create;
  pos := Pos(delimiter, txt);
  while pos > 0 do
  begin
    Result.Add(Copy(txt, 1, pos - 1));
    txt := Copy(txt, pos + 1, Length(txt));
    pos := Pos(delimiter, txt);
  end;
  Result.Add(txt);
end;


function IsSorted(lst : array of integer): boolean;
begin
  if length(lst) <= 1 then
    result := true
  else
    var
      i: integer;
      isDuplicate: boolean;
    begin
      isDuplicate := false;
      for i := 1 to length(lst) - 1 do
        if lst[i] = lst[i-1] then
          isDuplicate := true;
      if isDuplicate then
        result := false
      else
        result := IsSorted(copy(lst, 1, length(lst) - 1));
    end;
end;


function Intersection(interval1, interval2 : array of integer): string;
var
  start, end, intersectionStart, intersectionEnd: integer;
begin
  start := max(interval1[0], interval2[0]);
  end := min(interval1[1], interval2[1]);

  if start > end then
    result := 'NO'
  else
  begin
    intersectionStart := start;
    intersectionEnd := end;

    if IsPrime(intersectionEnd - intersectionStart + 1) then
      result := 'YES'
    else
      result := 'NO';
  end;
end;

function IsPrime(n : integer): boolean;
var
  i: integer;
begin
  if n <= 1 then
    result := false
  else if n <= 3 then
    result := true
  else if n mod 2 = 0 or n mod 3 = 0 then
    result := false
  else
  begin
    i := 5;
    while (i * i <= n) and (n mod i = 0) or (n mod (i + 2) = 0) do
      i := i + 6;

    if n mod i = 0 then
      result := false
    else
      result := true;
  end;
end;


