        sum := sum + Abs(arr[i]);
    end;

    Result := sum * product;
end;


function Minpath(grid : array of array of integer; k : integer): array of integer;
var
    N, i, j, min, min_i, min_j, temp : integer;
    min_list : array of integer;
begin
    N := length(grid);
    SetLength(min_list, k);
    for i := 0 to N-1 do
        for j := 0 to N-1 do
        begin
            min := grid[i][j];
            for var l := 0 to k-1 do
                for var m := 0 to N-1 do
                    for var n := 0 to N-1 do
                        if (m <> i) and (n <> j) and (grid[m][n] < min) then
                            min := grid[m][n];
            min_list[i mod k] := min;
        end;
    Result := min_list;
end;


function Tri(n : integer): array of real;
var
    i : integer;
    result : array of real;
begin
    SetLength(result, n + 1);
    result[0] := 3;
    for i := 1 to n do
    begin
        if i mod 2 = 0 then
            result[i] := result[i - 1] + i div 2
        else
            result[i] := result[i - 1] + result[i - 2] + result[i - 1] + i;
    end;
    Tri := result;
end;


function Digits(n : integer): integer;
