function FixSpaces(text : string): string;
var
    i, j: integer;
    newText: string;
begin
    newText := '';
    i := 1;
    while i <= length(text) do
    begin
        if text[i] = ' ' then
        begin
            if (i > 1) and (text[i-1] = ' ') and (i < length(text)) and (text[i+1] = ' ') then
                newText := newText + '_'
            else
                newText := newText + '-';
        end
        else
            newText := newText + text[i];
        i := i + 1;
    end;
    FixSpaces := newText;
end;


