  Result := '';

  for i := 0 to High(words) do
  begin
    length := Length(words[i]);
    isPrime := True;

    for j := 2 to sqrt(length) do
      if (length mod j) = 0 then
      begin
        isPrime := False;
        break;
      end;

    if isPrime then
      Result := Result + ' ' + words[i];
  end;

  SetLength(words, 0);
end;


function Simplify(x, n : string): boolean;
var
    x_num, x_den, n_num, n_den : integer;
    gcd : integer;
begin
    // Split the numerator and denominator of x and n
    Val(Copy(x, 1, Pos('/', x)-1), x_num, gcd);
    Val(Copy(x, Pos('/', x)+1, Length(x)), x_den, gcd);
    Val(Copy(n, 1, Pos('/', n)-1), n_num, gcd);
    Val(Copy(n, Pos('/', n)+1, Length(n)), n_den, gcd);

    // Check if x * n is a whole number
    Result := (x_num * n_den = n_num * x_den);
end;


function OrderByPoints(nums : array of integer): array of integer;
var
  i, j, temp, sum, max_index, max_sum: integer;
begin
  for i := 0 to High(nums) do
  begin
    max_sum := -1;
    max_index := -1;
    for j := i to High(nums) do
    begin
      sum := 0;
      temp := nums[j];
      while temp > 0 do
      begin
        sum := sum + temp mod 10;
        temp := temp div 10;
      end;
      if (sum > max_sum) or ((sum = max_sum) and (j < max_index)) then
      begin
        max_sum := sum;
        max_index := j;
      end;
    end;
    if max_index <> -1 then
    begin
      temp := nums[i];
      nums[i] := nums[max_index];
      nums[max_index] := temp;
    end;
  end;
  Result := nums;
end;


