function StrongestExtension(className : string; extensions : array of string): string;
var
    maxStrength : double;
    strongestExtension : string;
begin
    maxStrength := -1.0;
    strongestExtension := '';
    for var extension in extensions do
    begin
        var CAP := Length(UpperCase(extension));
        var SM := Length(LowerCase(extension));
        var strength := CAP - SM;
        if strength > maxStrength then
        begin
            maxStrength := strength;
            strongestExtension := extension;
        end;
    end;
    Result := className + '.' + strongestExtension;
end;


