function DoAlgebra(op : array of string; operand : array of integer): integer;
var
    i, j, k: integer;
    result, temp: integer;
begin
    result := operand[1];
    for i := 2 to length(operand) do
    begin
        temp := 0;
        for j := 1 to length(op) do
        begin
            if op[j] = '+' then
                temp := result + operand[i]
            else if op[j] = '-' then
                temp := result - operand[i]
            else if op[j] = '*' then
                temp := result * operand[i]
            else if op[j] = '//' then
                temp := result div operand[i]
            else if op[j] = '**' then
                temp := result * operand[i]
        end;
        result := temp;
    end;
    DoAlgebra := result;
end;


