function GenerateIntegers(a, b : integer): array of integer;
var
    i, j, k : integer;
    temp : integer;
    result : array of integer;
begin
    if a > b then
    begin
        temp := a;
        a := b;
        b := temp;
    end;

    SetLength(result, 0);
    for i := a to b do
    begin
        if i mod 2 = 0 then
        begin
            SetLength(result, Length(result) + 1);
            result[Length(result) - 1] := i;
        end;
    end;

    for j := 0 to Length(result) - 1 do
    begin
        for k := 0 to Length(result) - 1 do
        begin
            if result[j] < result[k] then
            begin
                temp := result[j];
                result[j] := result[k];
                result[k] := temp;
            end;
        end;
    end;

    GenerateIntegers := result;
end;
